To prevent diff churn and maintain consistency across generated artifacts, we should ensure the generated JSON arrays are strictly ordered by their ID fields using `sortByIdByteOrder`.

```javascript
function buildOutput({ generatedAt, executionPlan, rows }) {
  const sortedRows = sortByIdByteOrder(
    asArray(rows).map((row) => ({
      ...row,
      bbox_candidates: sortByIdByteOrder(asArray(row.bbox_candidates), 'source_page_render_id'),
    })),
    'packet_id'
  );

  return {
    schema_version: 'figureasset_vlm_crop_proposal_output.v1',
    generated_at: generatedAt,
    generated_by: 'scripts/method-map/run-figureasset-vlm-crop-proposal-harness.mjs',
    issue: ISSUE_NUMBER,
    parent_issue: PARENT_ISSUE_NUMBER,
    depends_on_issue: DEPENDS_ON_ISSUE,
    chain: CHAIN_ID,
    request_plan_hash: {
      sha256: sha256Json(executionPlan),
    },
    output_boundary: {
      candidate_only: true,
      accepted_for_student_display: false,
      visual_qa_accepted: false,
      rights_approval: false,
      display_eligibility: false,
      source_visual_receipt_approval: false,
      method_map_truth: false,
      scoring_or_mark_scheme_truth: false,
    },
    response_schema_ref: '#/response_schema',
    response_schema: CROP_PROPOSAL_RESPONSE_SCHEMA,
    rows: sortedRows,
  };
}
```

