+    });
+    return findings;
+  }
+  for (const [key, child] of Object.entries(value)) {
+    if (keyLooksPrivateOrSecret(key)) {
+      findings.push({
+        path: [...pathSegments, key].join('/'),
+        reason: 'private_or_secret_key',
+      });
+      continue;
+    }
+    findings.push(...privateOrSecretFindings(child, [...pathSegments, key]));
+  }
