+      findings.push(...forbiddenOutputFieldFindings(item, [...pathSegments, String(index)]));
+    });
+    return findings;
+  }
+  for (const [key, child] of Object.entries(value)) {
+    if (FORBIDDEN_OUTPUT_FIELDS.has(key)) {
+      findings.push({
+        path: [...pathSegments, key].join('/'),
+        field: key,
+      });
+      continue;
+    }
+    findings.push(...forbiddenOutputFieldFindings(child, [...pathSegments, key]));
+  }
