+}
+
+export function validateCropProposalResponseRows({ packets, rows }) {
+  const diagnostics = [];
+  const packetById = new Map(asArray(packets).map((packet) => [packet.packet_id, packet]));
+  const candidateRows = asArray(rows);
+
+  for (const [rowIndex, row] of candidateRows.entries()) {
+    const rowPath = `rows/${rowIndex}`;
+    if (!row || typeof row !== 'object' || Array.isArray(row)) {
+      diagnostic(diagnostics, 'response_row_malformed', rowPath, 'response row must be an object');
+      continue;
+    }
+
+    const sourcePacket = packetById.get(row.packet_id);
+    if (!sourcePacket) {
+      diagnostic(diagnostics, 'packet_id_unknown', `${rowPath}/packet_id`, 'packet_id must reference an input packet');
+    } else if (row.precise_crop_source_map_row_id !== sourcePacket.precise_crop_source_map_row_id) {
+      diagnostic(
+        diagnostics,
+        'precise_crop_source_map_row_id_mismatch',
+        `${rowPath}/precise_crop_source_map_row_id`,
+        'row id must match the referenced packet'
+      );
+    }
+
+    if (!VISUAL_OBJECT_CLASSES.includes(row.visual_object_class)) {
+      diagnostic(diagnostics, 'visual_object_class_invalid', `${rowPath}/visual_object_class`, 'visual_object_class is not in the allowed enum');
+    }
+
+    if (!Array.isArray(row.bbox_candidates)) {
+      diagnostic(diagnostics, 'bbox_candidates_invalid', `${rowPath}/bbox_candidates`, 'bbox_candidates must be an array');
+      continue;
+    }
+
+    const renderIds = packetRenderIds(sourcePacket);
+    for (const [candidateIndex, candidate] of row.bbox_candidates.entries()) {
+      const candidatePath = `${rowPath}/bbox_candidates/${candidateIndex}`;
+      if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
+        diagnostic(diagnostics, 'bbox_candidate_malformed', candidatePath, 'bbox candidate must be an object');
+        continue;
+      }
+      if (!renderIds.has(candidate.source_page_render_id)) {
+        diagnostic(diagnostics, 'source_page_render_id_unknown', `${candidatePath}/source_page_render_id`, 'render id must reference the packet source renders');
+      }
+      const bbox = candidate.bbox_pixels;
+      if (!bbox || typeof bbox !== 'object' || Array.isArray(bbox)) {
+        diagnostic(diagnostics, 'bbox_pixels_invalid', `${candidatePath}/bbox_pixels`, 'bbox_pixels must be an object');
+      } else {
+        if (!isNonNegativeInteger(bbox.x)) diagnostic(diagnostics, 'bbox_x_invalid', `${candidatePath}/bbox_pixels/x`, 'x must be an integer >= 0');
+        if (!isNonNegativeInteger(bbox.y)) diagnostic(diagnostics, 'bbox_y_invalid', `${candidatePath}/bbox_pixels/y`, 'y must be an integer >= 0');
+        if (!isPositiveInteger(bbox.width)) diagnostic(diagnostics, 'bbox_width_invalid', `${candidatePath}/bbox_pixels/width`, 'width must be an integer >= 1');
+        if (!isPositiveInteger(bbox.height)) diagnostic(diagnostics, 'bbox_height_invalid', `${candidatePath}/bbox_pixels/height`, 'height must be an integer >= 1');
+      }
+      if (!COMPLETENESS_STATUSES.includes(candidate.completeness_status)) {
+        diagnostic(diagnostics, 'completeness_status_invalid', `${candidatePath}/completeness_status`, 'completeness_status is not in the allowed enum');
+      }
+      if (typeof candidate.confidence !== 'number' || !Number.isFinite(candidate.confidence) || candidate.confidence < 0 || candidate.confidence > 1) {
+        diagnostic(diagnostics, 'confidence_invalid', `${candidatePath}/confidence`, 'confidence must be a number from 0 to 1');
+      }
+      if (COMPLETENESS_STATUSES_REQUIRING_BLOCKER_REASON.has(candidate.completeness_status)
+        && (typeof candidate.blocker_reason !== 'string' || candidate.blocker_reason.trim() === '')) {
+        diagnostic(diagnostics, 'blocker_reason_required', `${candidatePath}/blocker_reason`, 'blocker_reason is required for incomplete or blocked candidates');
+      }
+      if (!('blocker_reason' in candidate)) {
+        diagnostic(diagnostics, 'blocker_reason_required', `${candidatePath}/blocker_reason`, 'blocker_reason must be present, even when null');
+      }
+    }
+  }
