+  const privateFindings = privateOrSecretFindings(candidateRows);
+  for (const finding of privateFindings) {
+    diagnostic(diagnostics, 'private_or_secret_response_field', finding.path, finding.reason);
+  }
+  const forbiddenFindings = forbiddenOutputFieldFindings(candidateRows);
+  for (const finding of forbiddenFindings) {
+    diagnostic(diagnostics, 'forbidden_response_claim_field', finding.path, `forbidden field ${finding.field}`);
+  }
