+async function runAuthorizedWorker({ packets, worker, createExternalVlmClient, executionPlan, diagnostics }) {
+  let networkSetupAttempted = false;
+  let externalClient = null;
+  let noWorkerConfigured = false;
+  if (typeof createExternalVlmClient === 'function') {
+    networkSetupAttempted = true;
+    externalClient = await createExternalVlmClient({ executionPlan });
+  }
+  if (typeof worker !== 'function') {
+    noWorkerConfigured = true;
+    diagnostics.push({
+      code: 'authorized_worker_not_configured',
+      severity: 'warning',
+      reason: 'authorization resolved, but no external VLM worker was supplied',
+    });
+    return {
+      rows: [],
+      workerCallCount: 0,
+      externalCallCount: 0,
+      networkSetupAttempted,
+      noWorkerConfigured,
+    };
+  }
+
+  const rows = [];
+  let workerCallCount = 0;
+  for (const packet of packets) {
+    const workerOutput = await worker({ packet, executionPlan, externalClient });
+    rows.push({
+      packet_id: packet.packet_id,
+      precise_crop_source_map_row_id: packet.precise_crop_source_map_row_id,
+      ...workerOutput,
+    });
+    workerCallCount += 1;
+  }
+
+  return {
+    rows,
+    workerCallCount,
+    externalCallCount: workerCallCount,
+    networkSetupAttempted,
+    noWorkerConfigured,
+  };
+}
